// Host-side tests for crypto/prims (HMAC, PBKDF2, AES-GCM, AES-CBC). No Android, no network.
// Expected values come from prims_vectors.inc, generated by gen_prims_vectors.py with
// implementations independent of the code under test (Python hmac/hashlib, `cryptography`);
// the RFC 6238 TOTP table in it is asserted against the RFC's published values by the generator.
#include <cstdio>
#include <cstring>
#include <random>
#include <string>
#include <vector>

#include "../prims.h"

using namespace prims;

static int g_checks = 0, g_failed = 0;
#define CHECK(cond) do { g_checks++; if (!(cond)) { g_failed++; std::printf("  FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond); } } while (0)

#include "prims_vectors.inc"

static Bytes unhex(const char* s) {
    Bytes b;
    const size_t n = std::strlen(s);
    for (size_t i = 0; i + 1 < n; i += 2) b.push_back(static_cast<uint8_t>(std::stoi(std::string(s + i, 2), nullptr, 16)));
    return b;
}
static std::string hex(const Bytes& b) {
    static const char* d = "0123456789abcdef";
    std::string s;
    for (uint8_t c : b) { s.push_back(d[c >> 4]); s.push_back(d[c & 15]); }
    return s;
}
static Bytes rnd(size_t n, uint32_t seed) { std::mt19937 g(seed); Bytes b(n); for (auto& x : b) x = static_cast<uint8_t>(g()); return b; }
static const uint8_t* P(const Bytes& b) { return b.empty() ? nullptr : b.data(); }
static Hash H(const char* name) { Hash h = Hash::Sha1; parseHash(name, h); return h; }

static void testHmac() {
    std::printf("hmac\n");
    for (const auto& v : kHmac) {
        Hash h; CHECK(parseHash(v.hash, h));
        const Bytes key = unhex(v.key), data = unhex(v.data);
        Bytes mac; CHECK(hmac(h, P(key), key.size(), P(data), data.size(), mac));
        CHECK(hex(mac) == v.mac);
    }
    // TOTP (RFC 6238): the code the authenticator derives from the MAC
    for (const auto& v : kTotp) {
        const Bytes key = unhex(v.key);
        uint8_t ctr[8]; for (int i = 7; i >= 0; --i) ctr[7 - i] = static_cast<uint8_t>(v.counter >> (8 * i));
        Bytes mac; CHECK(hmac(H(v.hash), key.data(), key.size(), ctr, 8, mac));
        const size_t off = mac.back() & 0x0F;
        const uint32_t bin = ((mac[off] & 0x7Fu) << 24) | (mac[off + 1] << 16) | (mac[off + 2] << 8) | mac[off + 3];
        char buf[16]; std::snprintf(buf, sizeof buf, "%08u", bin % 100000000u);
        CHECK(std::string(buf) == v.code);
    }
    // the channel contract
    Hash h = Hash::Sha1;
    CHECK(parseHash("sha1", h) && h == Hash::Sha1);
    CHECK(parseHash("sha256", h) && h == Hash::Sha256);
    CHECK(parseHash("sha512", h) && h == Hash::Sha512);
    for (const char* bad : {"SHA1", "sha-256", "sha384", "md5", "", "sha256 "}) CHECK(!parseHash(bad, h));
    Bytes out{1, 2, 3};
    const uint8_t k[] = {1}, d[] = {2};
    CHECK(!hmac(Hash::Sha256, k, 0, d, 1, out) && out.empty());                  // empty key rejected, out cleared
    CHECK(!hmac(Hash::Sha256, nullptr, 0, d, 1, out));
    CHECK(!hmac(Hash::Sha256, k, 1, nullptr, 5, out));                           // null data with a length
    CHECK(hmac(Hash::Sha256, k, 1, nullptr, 0, out) && out.size() == 32);        // empty data is fine
    CHECK(hmac(Hash::Sha1, k, 1, d, 1, out) && out.size() == 20);
    CHECK(hmac(Hash::Sha512, k, 1, d, 1, out) && out.size() == 64);
    const Bytes big = rnd(5 * 1024 * 1024, 7), bk = rnd(50, 8);                  // large input in one call
    Bytes m1, m2;
    CHECK(hmac(Hash::Sha256, bk.data(), bk.size(), big.data(), big.size(), m1));
    CHECK(hmac(Hash::Sha256, bk.data(), bk.size(), big.data(), big.size(), m2) && m1 == m2);
}

static void testPbkdf2() {
    std::printf("pbkdf2\n");
    for (const auto& v : kPbkdf2) {
        const Bytes pw = unhex(v.pw), salt = unhex(v.salt);
        Bytes dk; CHECK(pbkdf2(H(v.hash), P(pw), pw.size(), P(salt), salt.size(), v.iters, v.outLen, dk));
        CHECK(hex(dk) == v.dk);
    }
    Bytes out{9};
    const uint8_t pw[] = {'p'}, salt[] = {'s'};
    CHECK(!pbkdf2(Hash::Sha1, pw, 1, salt, 0, 1, 20, out) && out.empty());       // empty salt
    CHECK(!pbkdf2(Hash::Sha1, pw, 1, nullptr, 1, 1, 20, out));
    CHECK(!pbkdf2(Hash::Sha1, pw, 1, salt, 1, 0, 20, out));                      // zero iterations
    CHECK(!pbkdf2(Hash::Sha1, pw, 1, salt, 1, 1, 0, out));                       // zero length
    CHECK(!pbkdf2(Hash::Sha1, nullptr, 3, salt, 1, 1, 20, out));                 // null password with a length
    CHECK(pbkdf2(Hash::Sha1, nullptr, 0, salt, 1, 1, 20, out) && out.size() == 20);   // empty password is allowed
}

static void testGcm() {
    std::printf("aes-gcm\n");
    for (const auto& v : kGcm) {
        const Bytes key = unhex(v.key), iv = unhex(v.iv), aad = unhex(v.aad), pt = unhex(v.pt), want = unhex(v.ctTag);
        Bytes ct; CHECK(aesGcmSeal(key.data(), key.size(), iv.data(), iv.size(), P(aad), aad.size(), P(pt), pt.size(), ct));
        CHECK(ct == want);
        Bytes back; CHECK(aesGcmOpen(key.data(), key.size(), iv.data(), iv.size(), P(aad), aad.size(), want.data(), want.size(), back));
        CHECK(back == pt);
    }
    // tampering with ANY input makes Open fail and leaves nothing behind
    const Bytes key = rnd(32, 11), iv = rnd(12, 12), aad = rnd(9, 13), pt = rnd(77, 14);
    Bytes ct; CHECK(aesGcmSeal(key.data(), 32, iv.data(), 12, aad.data(), aad.size(), pt.data(), pt.size(), ct));
    CHECK(ct.size() == pt.size() + 16);
    Bytes out{1, 2, 3};
    for (size_t i = 0; i < ct.size(); ++i) {                                     // every ciphertext and tag byte
        Bytes t = ct; t[i] ^= 0x01;
        CHECK(!aesGcmOpen(key.data(), 32, iv.data(), 12, aad.data(), aad.size(), t.data(), t.size(), out) && out.empty());
    }
    { Bytes k = key; k[0] ^= 1; CHECK(!aesGcmOpen(k.data(), 32, iv.data(), 12, aad.data(), aad.size(), ct.data(), ct.size(), out)); }
    { Bytes v = iv; v[0] ^= 1; CHECK(!aesGcmOpen(key.data(), 32, v.data(), 12, aad.data(), aad.size(), ct.data(), ct.size(), out)); }
    { Bytes a = aad; a[0] ^= 1; CHECK(!aesGcmOpen(key.data(), 32, iv.data(), 12, a.data(), a.size(), ct.data(), ct.size(), out)); }
    CHECK(!aesGcmOpen(key.data(), 32, iv.data(), 12, nullptr, 0, ct.data(), ct.size(), out));   // AAD missing
    CHECK(!aesGcmOpen(key.data(), 32, iv.data(), 12, aad.data(), aad.size(), ct.data(), ct.size() - 1, out));   // truncated
    CHECK(!aesGcmOpen(key.data(), 32, iv.data(), 12, aad.data(), aad.size(), ct.data(), 15, out));             // shorter than a tag
    CHECK(aesGcmOpen(key.data(), 32, iv.data(), 12, aad.data(), aad.size(), ct.data(), ct.size(), out) && out == pt);

    // contract: 128- and 256-bit keys only, a non-empty IV
    for (size_t kl : {size_t(0), size_t(15), size_t(24), size_t(31), size_t(33)}) {
        const Bytes k = rnd(kl ? kl : 1, 15);
        CHECK(!aesGcmSeal(k.data(), kl, iv.data(), 12, nullptr, 0, pt.data(), pt.size(), out) && out.empty());
        CHECK(!aesGcmOpen(k.data(), kl, iv.data(), 12, nullptr, 0, ct.data(), ct.size(), out));
    }
    CHECK(!aesGcmSeal(key.data(), 32, iv.data(), 0, nullptr, 0, pt.data(), pt.size(), out));
    CHECK(!aesGcmSeal(key.data(), 32, nullptr, 12, nullptr, 0, pt.data(), pt.size(), out));
    CHECK(!aesGcmSeal(key.data(), 32, iv.data(), 12, nullptr, 3, pt.data(), pt.size(), out));   // null AAD with a length
    CHECK(!aesGcmSeal(key.data(), 32, iv.data(), 12, nullptr, 0, nullptr, 3, out));             // null plaintext with a length
    // empty plaintext: the output is just the tag, and opens back to nothing
    Bytes tagOnly; CHECK(aesGcmSeal(key.data(), 32, iv.data(), 12, nullptr, 0, nullptr, 0, tagOnly) && tagOnly.size() == 16);
    CHECK(aesGcmOpen(key.data(), 32, iv.data(), 12, nullptr, 0, tagOnly.data(), 16, out) && out.empty());
    // large message
    const Bytes big = rnd(3 * 1024 * 1024 + 5, 16);
    Bytes bct, bback;
    CHECK(aesGcmSeal(key.data(), 32, iv.data(), 12, nullptr, 0, big.data(), big.size(), bct));
    CHECK(aesGcmOpen(key.data(), 32, iv.data(), 12, nullptr, 0, bct.data(), bct.size(), bback) && bback == big);
}

static void testCbc() {
    std::printf("aes-cbc\n");
    for (const auto& v : kCbc) {
        const Bytes key = unhex(v.key), iv = unhex(v.iv), pt = unhex(v.pt), ct = unhex(v.ct);
        Bytes enc; CHECK(aesCbcEncrypt(key.data(), key.size(), iv.data(), 16, P(pt), pt.size(), enc));
        CHECK(enc == ct);
        Bytes dec; CHECK(aesCbcDecrypt(key.data(), key.size(), iv.data(), 16, ct.data(), ct.size(), dec));
        CHECK(dec == pt);
    }
    // ciphertexts with invalid PKCS#7 padding are rejected and leave nothing behind
    for (const auto& v : kCbcBad) {
        const Bytes key = unhex(v.key), iv = unhex(v.iv), ct = unhex(v.ct);
        Bytes out{7, 7};
        CHECK(!aesCbcDecrypt(key.data(), key.size(), iv.data(), 16, ct.data(), ct.size(), out) && out.empty());
    }
    const Bytes key = rnd(16, 21), iv = rnd(16, 22), pt = rnd(40, 23);
    Bytes ct; CHECK(aesCbcEncrypt(key.data(), 16, iv.data(), 16, pt.data(), pt.size(), ct) && ct.size() == 48);
    Bytes out{1};
    CHECK(!aesCbcDecrypt(key.data(), 16, iv.data(), 16, ct.data(), 47, out) && out.empty());       // not a multiple of 16
    CHECK(!aesCbcDecrypt(key.data(), 16, iv.data(), 16, ct.data(), 17, out));
    CHECK(!aesCbcDecrypt(key.data(), 16, iv.data(), 16, ct.data(), 0, out));                       // empty
    CHECK(!aesCbcDecrypt(key.data(), 16, iv.data(), 16, nullptr, 0, out));
    for (size_t kl : {size_t(0), size_t(8), size_t(15), size_t(17), size_t(31), size_t(33), size_t(64)}) {
        const Bytes k = rnd(kl ? kl : 1, 24);
        CHECK(!aesCbcEncrypt(k.data(), kl, iv.data(), 16, pt.data(), pt.size(), out) && out.empty());
        CHECK(!aesCbcDecrypt(k.data(), kl, iv.data(), 16, ct.data(), ct.size(), out));
    }
    for (size_t il : {size_t(0), size_t(8), size_t(12), size_t(15), size_t(17), size_t(32)}) {
        const Bytes v = rnd(il ? il : 1, 25);
        CHECK(!aesCbcEncrypt(key.data(), 16, v.data(), il, pt.data(), pt.size(), out));
        CHECK(!aesCbcDecrypt(key.data(), 16, v.data(), il, ct.data(), ct.size(), out));
    }
    CHECK(!aesCbcEncrypt(key.data(), 16, iv.data(), 16, nullptr, 4, out));                         // null with a length
    // a wrong IV garbles only the first block, as CBC does; the padding in the last block still checks out
    Bytes wrongIv = iv; wrongIv[0] ^= 0x80;
    Bytes d2; CHECK(aesCbcDecrypt(key.data(), 16, wrongIv.data(), 16, ct.data(), ct.size(), d2) && d2.size() == pt.size());
    CHECK(d2 != pt && std::memcmp(d2.data() + 16, pt.data() + 16, pt.size() - 16) == 0);
    // round trips at every small length and one large one
    for (size_t n = 0; n <= 70; ++n) {
        const Bytes p = rnd(n, 100 + static_cast<uint32_t>(n)); Bytes e, d;
        CHECK(aesCbcEncrypt(key.data(), 16, iv.data(), 16, P(p), p.size(), e));
        CHECK(e.size() == (n / 16 + 1) * 16);
        CHECK(aesCbcDecrypt(key.data(), 16, iv.data(), 16, e.data(), e.size(), d) && d == p);
    }
    const Bytes big = rnd(2 * 1024 * 1024 + 3, 26); Bytes be, bd;
    CHECK(aesCbcEncrypt(key.data(), 16, iv.data(), 16, big.data(), big.size(), be));
    CHECK(aesCbcDecrypt(key.data(), 16, iv.data(), 16, be.data(), be.size(), bd) && bd == big);
}

int main() {
    testHmac();
    testPbkdf2();
    testGcm();
    testCbc();
    std::printf("\n%d checks, %d failed\n", g_checks, g_failed);
    return g_failed ? 1 : 0;
}
